/* relay-data.js — bilingual data model for the CM15_4_RRE system-settings tool.
   Attaches RELAY to window. No build step; plain script. */
(function () {
  "use strict";

  // Helpers to keep parameter definitions terse.
  // enum option: { v: storedValue, ru, en }
  const opt = (v, ru, en) => ({ v, ru, en: en || ru });

  // Parameter definition fields:
  //   id, ru, en          label
  //   type                'enum' | 'number' | 'text' | 'readonly' | 'time' | 'live'
  //   value               current value (stored)
  //   unit {ru,en}        optional unit shown in its own column
  //   options []          for enum
  //   min,max,step        for number
  //   suffix              static unit appended to a number's display (e.g. "kV")
  //   hint {ru,en}        optional helper / validation hint
  const P = (def) => def;

  // ---------------------------------------------------------------------------
  // Configuration — faithful to the screenshot.
  // ---------------------------------------------------------------------------
  const configuration = {
    sections: [
      {
        id: "sysinfo",
        ru: "Сис. инфо",
        en: "System info",
        params: [
          P({ id: "fw", ru: "Прошивка v.", en: "Firmware v.", type: "readonly", value: "79.01.1" }),
          P({ id: "func0", ru: "Функциональность", en: "Functionality", type: "readonly", value: "РРЭ", valueEn: "FP" }),
        ],
      },
      {
        id: "config",
        ru: "Конфигурация",
        en: "Configuration",
        params: [
          P({
            id: "func", ru: "Функциональность", en: "Functionality", type: "enum",
            value: "rad4",
            options: [
              opt("rad4", "РРЭ(4) Радиальный", "FP(4) Radial"),
              opt("ring4", "РРЭ(4) Кольцевой", "FP(4) Ring"),
              opt("rad8", "РРЭ(8) Радиальный", "FP(8) Radial"),
              opt("trans", "Трансформатор", "Transformer"),
            ],
          }),
          P({
            id: "subfunc", ru: "Подфункциональность", en: "Sub-functionality", type: "enum",
            value: "normal",
            options: [
              opt("normal", "Нормальный", "Normal"),
              opt("extended", "Расширенный", "Extended"),
              opt("test", "Тестовый", "Test"),
            ],
          }),
          P({
            id: "module", ru: "Тип модуля управления", en: "Control module type", type: "enum",
            value: "15_4",
            options: [opt("15_4", "15_4", "15_4"), opt("15_8", "15_8", "15_8"), opt("30_4", "30_4", "30_4")],
          }),
          P({
            id: "vnom", ru: "Номинальное напряжение", en: "Nominal voltage", type: "number",
            value: 13.8, min: 0.1, max: 35, step: 0.01, unit: { ru: "кВ", en: "kV" },
            hint: { ru: "Диапазон 0,1–35 кВ", en: "Range 0.1–35 kV" },
          }),
          P({
            id: "fnom", ru: "Номинальная частота", en: "Nominal frequency", type: "enum",
            value: "60", unit: { ru: "Гц", en: "Hz" },
            options: [opt("50", "50", "50"), opt("60", "60", "60")],
          }),
          P({
            id: "termsrc", ru: 'Выводы в сторону источника "→"', en: 'Terminals toward source "→"', type: "enum",
            value: "x123",
            options: [opt("x123", "X1 X2 X3", "X1 X2 X3"), opt("x456", "X4 X5 X6", "X4 X5 X6")],
          }),
          P({
            id: "pwrsrc", ru: "Источник для мощности", en: "Source for power", type: "enum",
            value: "x123",
            options: [opt("x123", "X1 X2 X3", "X1 X2 X3"), opt("x456", "X4 X5 X6", "X4 X5 X6")],
          }),
          P({
            id: "iserole", ru: "ISE role", en: "ISE role", type: "enum",
            value: "slave1",
            options: [
              opt("master", "мастер", "master"),
              opt("slave1", "слейв1", "slave1"),
              opt("slave2", "слейв2", "slave2"),
            ],
          }),
          P({ id: "ndev", ru: "Кол-во устройств", en: "Amount of devices", type: "number", value: 2, min: 1, max: 16, step: 1 }),
          P({ id: "lognum", ru: "Логический номер", en: "Logical number", type: "number", value: 0, min: 0, max: 254, step: 1 }),
          P({
            id: "exmode", ru: "Режим обмена", en: "Exchange mode", type: "enum",
            value: "slow",
            options: [opt("slow", "Медленный", "Slow"), opt("fast", "Быстрый", "Fast")],
          }),
          P({
            id: "exspeed", ru: "Скорость обмена", en: "Exchange speed", type: "enum",
            value: "500", unit: { ru: "кбит/с", en: "kbps" },
            options: [opt("125", "125", "125"), opt("250", "250", "250"), opt("500", "500", "500"), opt("1000", "1000", "1000")],
          }),
          P({
            id: "msgtype", ru: "Тип сообщения", en: "Message type", type: "enum",
            value: "phharm",
            options: [
              opt("phharm", "Фазоры гармоники", "Phasors harmonics"),
              opt("phasors", "Фазоры", "Phasors"),
              opt("raw", "Сырые данные", "Raw data"),
            ],
          }),
          P({
            id: "busring", ru: "Шина или кольцо", en: "Bus or Ring", type: "enum",
            value: "bus",
            options: [opt("bus", "Шина", "Bus"), opt("ring", "Кольцо", "Ring")],
          }),
          P({
            id: "mmpout", ru: "Режим выхода с ММП", en: "MMP output mode", type: "enum",
            value: "door",
            options: [opt("door", "Положение двери", "Door position"), opt("alarm", "Сигнализация", "Alarm"), opt("off", "Отключено", "Off")],
          }),
          P({
            id: "ovmode", ru: "Режим порта ОВ", en: "FO port mode", type: "enum",
            value: "door",
            options: [opt("door", "Положение двери", "Door position"), opt("data", "Передача данных", "Data transfer"), opt("off", "Отключено", "Off")],
          }),
          P({
            id: "ovtype", ru: "Тип порта ОВ", en: "FO port type", type: "enum",
            value: "reverse",
            options: [opt("reverse", "Обратный", "Reverse"), opt("direct", "Прямой", "Direct")],
          }),
          P({
            id: "pucheck", ru: "Проверка наличия ПУ", en: "Control point presence check", type: "enum",
            value: "on",
            options: [opt("on", "Введено", "Enabled"), opt("off", "Выведено", "Disabled")],
          }),
          P({
            id: "lrblock", ru: "Блокир. в режиме Местн./Дистанц.", en: "Block in Local/Remote mode", type: "enum",
            value: "off",
            options: [opt("on", "Введено", "Enabled"), opt("off", "Выведено", "Disabled")],
          }),
        ],
      },
    ],
  };

  // ---------------------------------------------------------------------------
  // Power supply
  // ---------------------------------------------------------------------------
  const powerSupply = {
    sections: [
      {
        id: "psu", ru: "Питание", en: "Power supply",
        params: [
          P({ id: "psrc", ru: "Источник питания", en: "Power source", type: "enum", value: "ac", options: [opt("ac", "Сеть AC", "AC mains"), opt("dc", "Постоянный ток DC", "DC"), opt("dual", "Резервированное", "Redundant")] }),
          P({ id: "vin", ru: "Входное напряжение", en: "Input voltage", type: "live", value: 232, unit: { ru: "В", en: "V" }, jitter: 1.5, base: 230 }),
          P({ id: "battpresent", ru: "Резервный аккумулятор", en: "Backup battery", type: "enum", value: "on", options: [opt("on", "Введено", "Enabled"), opt("off", "Выведено", "Disabled")] }),
          P({ id: "battv", ru: "Напряжение аккумулятора", en: "Battery voltage", type: "live", value: 26.8, unit: { ru: "В", en: "V" }, jitter: 0.15, base: 26.8 }),
          P({ id: "lowvthr", ru: "Порог низкого напряжения", en: "Low-voltage threshold", type: "number", value: 187, min: 100, max: 250, step: 1, unit: { ru: "В", en: "V" } }),
        ],
      },
    ],
  };

  // ---------------------------------------------------------------------------
  // Real-time clock (live)
  // ---------------------------------------------------------------------------
  const rtc = {
    sections: [
      {
        id: "clock", ru: "Часы", en: "Clock",
        params: [
          P({ id: "now", ru: "Текущее время", en: "Current time", type: "clock", value: "" }),
          P({ id: "tz", ru: "Часовой пояс", en: "Time zone", type: "enum", value: "utc3", options: [opt("utc0", "UTC+0", "UTC+0"), opt("utc3", "UTC+3 (Москва)", "UTC+3 (Moscow)"), opt("utc5", "UTC+5", "UTC+5")] }),
          P({ id: "sync", ru: "Синхронизация", en: "Synchronization", type: "enum", value: "ntp", options: [opt("ntp", "NTP", "NTP"), opt("irig", "IRIG-B", "IRIG-B"), opt("manual", "Вручную", "Manual")] }),
          P({ id: "ntpsrv", ru: "Сервер NTP", en: "NTP server", type: "text", value: "ntp.local" }),
          P({ id: "dst", ru: "Переход на летнее время", en: "Daylight saving", type: "enum", value: "off", options: [opt("on", "Введено", "Enabled"), opt("off", "Выведено", "Disabled")] }),
        ],
      },
    ],
  };

  // ---------------------------------------------------------------------------
  // Measurements (live read-only)
  // ---------------------------------------------------------------------------
  const measurements = {
    sections: [
      {
        id: "meas", ru: "Мгновенные значения", en: "Instantaneous values",
        params: [
          P({ id: "ua", ru: "Напряжение Ua", en: "Voltage Ua", type: "live", value: 7.97, unit: { ru: "кВ", en: "kV" }, jitter: 0.02, base: 7.96 }),
          P({ id: "ub", ru: "Напряжение Ub", en: "Voltage Ub", type: "live", value: 7.95, unit: { ru: "кВ", en: "kV" }, jitter: 0.02, base: 7.95 }),
          P({ id: "uc", ru: "Напряжение Uc", en: "Voltage Uc", type: "live", value: 7.98, unit: { ru: "кВ", en: "kV" }, jitter: 0.02, base: 7.97 }),
          P({ id: "ia", ru: "Ток Ia", en: "Current Ia", type: "live", value: 124.2, unit: { ru: "А", en: "A" }, jitter: 1.2, base: 124 }),
          P({ id: "ib", ru: "Ток Ib", en: "Current Ib", type: "live", value: 122.8, unit: { ru: "А", en: "A" }, jitter: 1.2, base: 123 }),
          P({ id: "ic", ru: "Ток Ic", en: "Current Ic", type: "live", value: 125.6, unit: { ru: "А", en: "A" }, jitter: 1.2, base: 125 }),
          P({ id: "p", ru: "Активная мощность P", en: "Active power P", type: "live", value: 2.84, unit: { ru: "МВт", en: "MW" }, jitter: 0.03, base: 2.84 }),
          P({ id: "freq", ru: "Частота", en: "Frequency", type: "live", value: 60.0, unit: { ru: "Гц", en: "Hz" }, jitter: 0.02, base: 60 }),
          P({ id: "cosphi", ru: "Коэффициент мощности", en: "Power factor", type: "live", value: 0.94, unit: { ru: "", en: "" }, jitter: 0.01, base: 0.94 }),
        ],
      },
    ],
  };

  // ---------------------------------------------------------------------------
  // General control-panel settings
  // ---------------------------------------------------------------------------
  const panelGeneral = {
    sections: [{
      id: "pgen", ru: "Общие настройки", en: "General settings",
      params: [
        P({ id: "backlight", ru: "Подсветка дисплея", en: "Display backlight", type: "number", value: 80, min: 0, max: 100, step: 5, unit: { ru: "%", en: "%" } }),
        P({ id: "timeout", ru: "Тайм-аут панели", en: "Panel timeout", type: "number", value: 120, min: 10, max: 600, step: 10, unit: { ru: "с", en: "s" } }),
        P({ id: "lang", ru: "Язык интерфейса", en: "Interface language", type: "enum", value: "ru", options: [opt("ru", "Русский", "Russian"), opt("en", "Английский", "English")] }),
        P({ id: "lock", ru: "Блокировка клавиатуры", en: "Keypad lock", type: "enum", value: "off", options: [opt("on", "Введено", "Enabled"), opt("off", "Выведено", "Disabled")] }),
      ],
    }],
  };

  // A button config — used for every "Кнопка N" node.
  const buttonConfig = (label) => ({
    sections: [{
      id: "btn", ru: "Назначение кнопки", en: "Button assignment",
      params: [
        P({ id: "action", ru: "Действие", en: "Action", type: "enum", value: "none", options: [opt("none", "Нет", "None"), opt("trip", "Отключение", "Trip"), opt("close", "Включение", "Close"), opt("reset", "Сброс", "Reset"), opt("nav", "Навигация", "Navigation")] }),
        P({ id: "confirm", ru: "Требует подтверждения", en: "Requires confirmation", type: "enum", value: "on", options: [opt("on", "Введено", "Enabled"), opt("off", "Выведено", "Disabled")] }),
        P({ id: "led", ru: "Связанный светодиод", en: "Linked LED", type: "enum", value: "none", options: [opt("none", "Нет", "None"), opt("1", "LED 1", "LED 1"), opt("2", "LED 2", "LED 2"), opt("3", "LED 3", "LED 3")] }),
        P({ id: "label", ru: "Метка", en: "Label", type: "text", value: label }),
      ],
    }],
  });

  const ledConfig = {
    sections: [{
      id: "leds", ru: "Светодиоды", en: "LED indicators",
      params: [
        P({ id: "led1", ru: "LED 1 — функция", en: "LED 1 — function", type: "enum", value: "trip", options: [opt("trip", "Отключение", "Trip"), opt("warn", "Предупреждение", "Warning"), opt("comm", "Связь", "Comms"), opt("off", "Выкл", "Off")] }),
        P({ id: "led2", ru: "LED 2 — функция", en: "LED 2 — function", type: "enum", value: "warn", options: [opt("trip", "Отключение", "Trip"), opt("warn", "Предупреждение", "Warning"), opt("comm", "Связь", "Comms"), opt("off", "Выкл", "Off")] }),
        P({ id: "latch", ru: "Фиксация", en: "Latching", type: "enum", value: "on", options: [opt("on", "Введено", "Enabled"), opt("off", "Выведено", "Disabled")] }),
      ],
    }],
  };

  const ethernet = {
    sections: [{
      id: "eth", ru: "Ethernet", en: "Ethernet",
      params: [
        P({ id: "dhcp", ru: "DHCP", en: "DHCP", type: "enum", value: "off", options: [opt("on", "Введено", "Enabled"), opt("off", "Выведено", "Disabled")] }),
        P({ id: "ip", ru: "IP-адрес", en: "IP address", type: "ip", value: "192.168.1.50" }),
        P({ id: "mask", ru: "Маска подсети", en: "Subnet mask", type: "ip", value: "255.255.255.0" }),
        P({ id: "gw", ru: "Шлюз", en: "Gateway", type: "ip", value: "192.168.1.1" }),
        P({ id: "proto", ru: "Протокол", en: "Protocol", type: "enum", value: "iec61850", options: [opt("iec61850", "IEC 61850", "IEC 61850"), opt("modbus", "Modbus TCP", "Modbus TCP"), opt("dnp3", "DNP3", "DNP3")] }),
        P({ id: "port", ru: "Порт", en: "Port", type: "number", value: 102, min: 1, max: 65535, step: 1 }),
      ],
    }],
  };

  const wifi = {
    sections: [{
      id: "wifi", ru: "Wi-Fi", en: "Wi-Fi",
      params: [
        P({ id: "wen", ru: "Wi-Fi", en: "Wi-Fi", type: "enum", value: "on", options: [opt("on", "Введено", "Enabled"), opt("off", "Выведено", "Disabled")] }),
        P({ id: "ssid", ru: "Имя сети (SSID)", en: "Network (SSID)", type: "text", value: "Substation-7G" }),
        P({ id: "sec", ru: "Безопасность", en: "Security", type: "enum", value: "wpa2", options: [opt("open", "Открытая", "Open"), opt("wpa2", "WPA2", "WPA2"), opt("wpa3", "WPA3", "WPA3")] }),
        P({ id: "band", ru: "Диапазон", en: "Band", type: "enum", value: "5", options: [opt("2.4", "2,4 ГГц", "2.4 GHz"), opt("5", "5 ГГц", "5 GHz")] }),
        P({ id: "signal", ru: "Уровень сигнала", en: "Signal level", type: "live", value: -54, unit: { ru: "дБм", en: "dBm" }, jitter: 2, base: -54 }),
      ],
    }],
  };

  // Generic small set for nodes we don't fully spec — feels alive, never empty.
  const genericSet = (ru, en) => ({
    sections: [{
      id: "g", ru, en,
      params: [
        P({ id: "ge", ru: "Состояние", en: "State", type: "enum", value: "on", options: [opt("on", "Введено", "Enabled"), opt("off", "Выведено", "Disabled")] }),
        P({ id: "gt", ru: "Уставка", en: "Threshold", type: "number", value: 110, min: 0, max: 200, step: 1, unit: { ru: "%", en: "%" } }),
        P({ id: "gd", ru: "Задержка", en: "Time delay", type: "number", value: 0.2, min: 0, max: 10, step: 0.05, unit: { ru: "с", en: "s" } }),
      ],
    }],
  });

  // ---------------------------------------------------------------------------
  // Tree. node: { id, ru, en, data?, children?, defaultOpen? }
  // ---------------------------------------------------------------------------
  const buttonLabels = ["1", "2", "3", "4", "5", "6", "7", "8", "9", "0", "[.]", "[M]", "CLOSE", "TRIP"];
  const buttonNodes = buttonLabels.map((l) => ({
    id: "btn_" + l, ru: "Кнопка " + l, en: "Button " + l, data: buttonConfig(l),
  }));

  const tree = [
    {
      id: "root", ru: "Системные параметры", en: "System parameters", defaultOpen: true,
      children: [
        { id: "configuration", ru: "Конфигурация", en: "Configuration", data: configuration },
        { id: "psu", ru: "Блок питания", en: "Power supply", data: powerSupply },
        { id: "rtc", ru: "Часы реального времени", en: "Real-time clock", data: rtc },
        {
          id: "panel", ru: "Панель управления", en: "Control panel", defaultOpen: true,
          children: [
            { id: "panel_general", ru: "Общие настройки", en: "General settings", data: panelGeneral },
            { id: "buttons", ru: "Настройки кнопок", en: "Button settings", children: buttonNodes },
            { id: "leds", ru: "Настройки светодиодов", en: "LED settings", data: ledConfig },
          ],
        },
        { id: "measurements", ru: "Измерения", en: "Measurements", data: measurements },
        {
          id: "logs", ru: "Счетчики и журналы", en: "Counters and logs", defaultOpen: true,
          children: [
            { id: "loadlog", ru: "Журнал нагрузок", en: "Load log", data: genericSet("Журнал нагрузок", "Load log") },
            { id: "osc", ru: "Осциллограф", en: "Oscilloscope", data: genericSet("Осциллограф", "Oscilloscope") },
            { id: "harm", ru: "Гармоники", en: "Harmonics", data: genericSet("Гармоники", "Harmonics") },
            { id: "fault", ru: "Определение места повреждения", en: "Fault location", data: genericSet("Определение места повреждения", "Fault location") },
            { id: "sfi", ru: "SFI settings", en: "SFI settings", data: genericSet("SFI", "SFI") },
            {
              id: "sags", ru: "Sags and Swells", en: "Sags and Swells",
              children: [
                { id: "sag", ru: "Sag settings", en: "Sag settings", data: genericSet("Провалы", "Sags") },
                { id: "swell", ru: "Swell settings", en: "Swell settings", data: genericSet("Перенапряжения", "Swells") },
              ],
            },
            {
              id: "agt", ru: "Common AGT", en: "Common AGT",
              children: [
                { id: "agt_annual", ru: "Annual AGT settings", en: "Annual AGT settings", data: genericSet("Годовой AGT", "Annual AGT") },
                { id: "agt_weekly", ru: "Weekly AGT settings", en: "Weekly AGT settings", data: genericSet("Недельный AGT", "Weekly AGT") },
              ],
            },
          ],
        },
        { id: "wifi", ru: "Настройки WiFi", en: "WiFi settings", data: wifi },
        { id: "ethernet", ru: "Настройки Ethernet", en: "Ethernet settings", data: ethernet },
      ],
    },
  ];

  window.RELAY = { tree, device: { name: "CM15_4_RRE", feeder: "New Feeder", model: "CM15_…" } };
})();

