    lock: <><rect x="4" y="8" width="10" height="6.5" rx="1" /><path d="M6 8V6a3 3 0 0 1 6 0v2" /></>,
    wifi: <><path d="M2.5 6.5a9 9 0 0 1 13 0" /><path d="M5 9a5.5 5.5 0 0 1 8 0" /><path d="M7.5 11.5a2 2 0 0 1 3 0" /><circle cx="9" cy="13.6" r=".4" /></>,
    clock: <><circle cx="9" cy="9" r="6" /><path d="M9 5.5V9l2.5 1.5" /></>,
    grid: <><rect x="3" y="3" width="5" height="5" rx="1" /><rect x="10" y="3" width="5" height="5" rx="1" /><rect x="3" y="10" width="5" height="5" rx="1" /><rect x="10" y="10" width="5" height="5" rx="1" /></>,
    bolt: <path d="M10 2 4 10h4l-1 6 6-8H9z" />,
  };
  return <svg viewBox="0 0 18 18" style={s} aria-hidden="true">{paths[name] || null}</svg>;
}

/* ---- bilingual label ---- */
function Lbl({ ru, en, lang, className }) {
  if (lang === "ru") return <span className={className}>{ru}</span>;
  if (lang === "en") return <span className={className}>{en}</span>;
  // both
  return (
    <span className={"lbl-both " + (className || "")}>
      <span className="lbl-primary">{ru}</span>
      {en && en !== ru ? <span className="lbl-secondary">{en}</span> : null}
    </span>
  );
}

/* =========================================================================
   FIELD EDITORS
   ========================================================================= */
function EnumField({ param, value, lang, onChange }) {
  const optLabel = (o) => (lang === "en" ? o.en : o.ru);
  return (
    <div className="cell-edit">
      <select className="rl-select" value={value} onChange={(e) => onChange(e.target.value)}>
        {param.options.map((o) => (
          <option key={o.v} value={o.v}>{optLabel(o)}{lang === "both" && o.en !== o.ru ? ` · ${o.en}` : ""}</option>
        ))}
      </select>
      <Icon name="chevron" size={13} />
    </div>
  );
}

function NumberField({ param, value, onChange }) {
  const num = typeof value === "number" ? value : parseFloat(value);
  const invalid = isNaN(num) || (param.min != null && num < param.min) || (param.max != null && num > param.max);
  return (
    <div className="cell-edit">
      <input
        className={"rl-input num" + (invalid ? " invalid" : "")}
        type="text" inputMode="decimal" value={value}
        onChange={(e) => onChange(e.target.value)}
      />
      {invalid ? <Icon name="alert" size={13} /> : null}
    </div>
  );
}

function TextField({ value, onChange }) {
  return <div className="cell-edit"><input className="rl-input" type="text" value={value} onChange={(e) => onChange(e.target.value)} /></div>;
}

const IP_RE = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;
function IpField({ value, onChange }) {
  const invalid = !IP_RE.test(value.trim());
  return (
    <div className="cell-edit">
      <input className={"rl-input mono" + (invalid ? " invalid" : "")} type="text" value={value} onChange={(e) => onChange(e.target.value)} />
      {invalid ? <Icon name="alert" size={13} /> : null}
    </div>
  );
}

function LiveValue({ value, decimals }) {
  return <span className="live-val mono">{typeof value === "number" ? value.toFixed(decimals) : value}<span className="live-dot" /></span>;
}

function ClockValue() {
  const [now, setNow] = useState(new Date());
  useEffect(() => { const t = setInterval(() => setNow(new Date()), 1000); return () => clearInterval(t); }, []);
  const pad = (n) => String(n).padStart(2, "0");
  return <span className="mono">{`${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}  ${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`}<span className="live-dot" /></span>;
}

/* =========================================================================
   PARAM ROW + TABLE
   ========================================================================= */
function ParamRow({ param, value, live, lang, dirty, onChange, index }) {
  const unit = param.unit ? (lang === "en" ? param.unit.en : param.unit.ru) : "";
  let editor;
  switch (param.type) {
    case "enum": editor = <EnumField param={param} value={value} lang={lang} onChange={onChange} />; break;
    case "number": editor = <NumberField param={param} value={value} onChange={onChange} />; break;
    case "text": editor = <TextField value={value} onChange={onChange} />; break;
    case "ip": editor = <IpField value={value} onChange={onChange} />; break;
    case "clock": editor = <div className="cell-static"><ClockValue /></div>; break;
    case "live": editor = <div className="cell-static"><LiveValue value={live != null ? live : param.value} decimals={Math.abs(param.value) < 10 ? 2 : (Number.isInteger(param.value) ? 0 : 1)} /></div>; break;
    case "readonly":
    default:
      editor = <div className="cell-static"><Lbl ru={String(param.value)} en={param.valueEn || String(param.value)} lang={lang} /></div>;
  }
  const showHint = param.type === "number" && param.hint;
  const numInvalid = param.type === "number" && (() => { const n = parseFloat(value); return isNaN(n) || (param.min != null && n < param.min) || (param.max != null && n > param.max); })();

  return (
    <tr className={"param-row" + (dirty ? " dirty" : "") + (index % 2 ? " odd" : "")}>
      <td className="c-name">
        {dirty ? <span className="dirty-dot" title="Изменено / Modified" /> : null}
        <Lbl ru={param.ru} en={param.en} lang={lang} />
      </td>
      <td className="c-unit">{unit}</td>
      <td className="c-value">
        {editor}
        {showHint ? <div className={"field-hint" + (numInvalid ? " err" : "")}>{lang === "en" ? param.hint.en : param.hint.ru}</div> : null}
      </td>
    </tr>
  );
}

function ParamTable({ data, nodeKey, values, live, lang, dirtySet, onChange }) {
  return (
    <div className="param-scroll">
      {data.sections.map((sec) => (
        <div className="param-section" key={sec.id}>
          <div className="section-head">
            <span className="section-toggle"><Icon name="chevron" size={12} /></span>
            <Lbl ru={sec.ru} en={sec.en} lang={lang} />
          </div>
          <table className="param-table">
            <tbody>
              {sec.params.map((p, i) => {
                const key = nodeKey + "." + p.id;
                const v = key in values ? values[key] : p.value;
                return (
                  <ParamRow
                    key={p.id} param={p} value={v} live={live[key]} lang={lang} index={i}
                    dirty={dirtySet.has(key)}
                    onChange={(nv) => onChange(key, nv)}
                  />
                );
              })}
            </tbody>
          </table>
        </div>
      ))}
    </div>
  );
}

/* =========================================================================
   TREE
   ========================================================================= */
function flattenLabels(node, lang) {
  return (lang === "en" ? node.en : node.ru) + " " + (node.en || "") + " " + (node.ru || "");
}
function nodeMatches(node, q, lang) {
  if (!q) return true;
  if (flattenLabels(node, lang).toLowerCase().includes(q)) return true;
  if (node.children) return node.children.some((c) => nodeMatches(c, q, lang));
  return false;
}

function TreeNode({ node, depth, selected, openSet, onToggle, onSelect, lang, query }) {
  const hasKids = node.children && node.children.length > 0;
  const isOpen = openSet.has(node.id) || (query && nodeMatches(node, query, lang) && hasKids);
  if (query && !nodeMatches(node, query, lang)) return null;
  const isSel = selected === node.id;
  return (
    <div className="tree-node">
      <div
        className={"tree-row" + (isSel ? " sel" : "") + (hasKids ? " has-kids" : "")}
        style={{ paddingLeft: 8 + depth * 16 }}
        onClick={() => { if (hasKids && !node.data) onToggle(node.id); else onSelect(node.id); }}
      >
        {hasKids ? (
          <span className={"tw-toggle" + (isOpen ? " open" : "")} onClick={(e) => { e.stopPropagation(); onToggle(node.id); }}>
            <Icon name="chevron" size={12} />
          </span>
        ) : <span className="tw-spacer" />}
        <span className="tree-label"><Lbl ru={node.ru} en={node.en} lang={lang} /></span>
      </div>
      {hasKids && isOpen ? (
        <div className="tree-children">
          {node.children.map((c) => (
            <TreeNode key={c.id} node={c} depth={depth + 1} selected={selected} openSet={openSet}
              onToggle={onToggle} onSelect={onSelect} lang={lang} query={query} />
          ))}
        </div>
      ) : null}
    </div>
  );
}

Object.assign(window, {
  Icon, Lbl, ParamTable, ParamRow, TreeNode, nodeMatches,
  EnumField, NumberField, TextField, IpField, LiveValue, ClockValue,
});

/* relay-app.jsx — application shell, state, Tweaks. */
const { useState: useS, useEffect: useE, useMemo: useM, useRef: useR } = React;

const TWEAK_DEFAULTS = /*EDITMODE-BEGIN*/{
  "theme": "refined",
  "accent": "#2f6fb0",
  "lang": "both",
  "density": "cozy",
  "liveData": true
}/*EDITMODE-END*/;

/* ---- build lookup maps from the tree ---- */
const NODE_BY_ID = {};
const PARENT_OF = {};
const LIVE_PARAMS = [];
(function index(nodes, parent) {
  nodes.forEach((n) => {
    NODE_BY_ID[n.id] = n;
    if (parent) PARENT_OF[n.id] = parent;
    if (n.data) {
      n.data.sections.forEach((s) => s.params.forEach((p) => {
        if (p.type === "live") LIVE_PARAMS.push({ key: n.id + "." + p.id, base: p.base != null ? p.base : p.value, jitter: p.jitter || 0 });
      }));
    }
    if (n.children) index(n.children, n.id);
  });
})(window.RELAY.tree, null);

function defaultOpenSet() {
  const s = new Set();
  (function walk(nodes) { nodes.forEach((n) => { if (n.defaultOpen) s.add(n.id); if (n.children) walk(n.children); }); })(window.RELAY.tree);
  // open ancestors of default selection
  return s;
}

function App() {
  const [t, setTweak] = useTweaks(TWEAK_DEFAULTS);
  const lang = t.lang;
  const [selected, setSelected] = useS("configuration");
  const [openSet, setOpenSet] = useS(defaultOpenSet());
  const [query, setQuery] = useS("");
  const [values, setValues] = useS({});
  const [dirty, setDirty] = useS(() => new Set());
  const [history, setHistory] = useS([]);
  const [live, setLive] = useS({});
  const [diffOnly, setDiffOnly] = useS(false);
  const [toast, setToast] = useS(null);
  const [drawer, setDrawer] = useS(false);

  const node = NODE_BY_ID[selected];

  /* live data ticking */
  useE(() => {
    if (!t.liveData) return;
    const tick = () => {
      setLive((prev) => {
        const next = { ...prev };
        LIVE_PARAMS.forEach((lp) => {
          const drift = (Math.random() - 0.5) * 2 * lp.jitter;
          next[lp.key] = lp.base + drift;
        });
        return next;
      });
    };
    tick();
    const id = setInterval(tick, 1400);
    return () => clearInterval(id);
  }, [t.liveData]);

  /* connection status pulse — derive "last update" */
  const [pulse, setPulse] = useS(0);
  useE(() => { const id = setInterval(() => setPulse((p) => p + 1), 1400); return () => clearInterval(id); }, []);

  function selectNode(id) {
    const n = NODE_BY_ID[id];
    if (!n) return;
    if (n.children && !n.data) { toggle(id); return; }
    setSelected(id);
    setDrawer(false);
  }
  function toggle(id) {
    setOpenSet((prev) => { const s = new Set(prev); s.has(id) ? s.delete(id) : s.add(id); return s; });
  }
  function changeValue(key, val) {
    setValues((prev) => {
      const had = key in prev;
      setHistory((h) => [...h, { key, prev: had ? prev[key] : undefined, had }]);
      return { ...prev, [key]: val };
    });
    setDirty((prev) => { const s = new Set(prev); s.add(key); return s; });
  }
  function undo() {
    setHistory((h) => {
      if (!h.length) return h;
      const last = h[h.length - 1];
      setValues((prev) => { const n = { ...prev }; if (last.had) n[last.key] = last.prev; else delete n[last.key]; return n; });
      setDirty((prev) => { const s = new Set(prev); if (!last.had) s.delete(last.key); return s; });
      return h.slice(0, -1);
    });
  }
  function save() {
    setDirty(new Set());
    setHistory([]);
    flash(lang === "en" ? "Configuration saved" : lang === "ru" ? "Конфигурация сохранена" : "Сохранено · Saved");
  }
  function revertAll() {
    setValues({}); setDirty(new Set()); setHistory([]);
    flash(lang === "en" ? "Reverted to saved" : "Возврат · Reverted");
  }
  function flash(msg) { setToast(msg); clearTimeout(flash._t); flash._t = setTimeout(() => setToast(null), 2200); }

  const dirtyCount = dirty.size;

  /* build breadcrumb path of node labels */
  const crumbs = useM(() => {
    const path = []; let cur = selected;
    while (cur) { path.unshift(NODE_BY_ID[cur]); cur = PARENT_OF[cur]; }
    return path;
  }, [selected]);

  /* filtered data for diff-only */
  const viewData = useM(() => {
    if (!node || !node.data) return null;
    if (!diffOnly) return node.data;
    const sections = node.data.sections
      .map((s) => ({ ...s, params: s.params.filter((p) => dirty.has(node.id + "." + p.id)) }))
      .filter((s) => s.params.length);
    return { sections };
  }, [node, diffOnly, dirty, values]);

  const L = (ru, en) => (lang === "en" ? en : lang === "ru" ? ru : ru);
  const dev = window.RELAY.device;

  return (
    <div className="app-root" data-theme={t.theme} data-density={t.density} style={{ "--accent": t.accent }}>
      {/* ===== TITLE BAR ===== */}
      <header className="titlebar">
        <button className="tb-home" title="Главная / Home"><Icon name="home" size={17} /></button>
        <div className="tb-title">
          <span className="tb-feeder">{dev.feeder}</span>
          <span className="tb-arrow">›</span>
          <span className="tb-device">{dev.name}</span>
          <span className="tb-sep">—</span>
          <span className="tb-page"><Lbl ru="Системные настройки" en="System settings" lang={lang} /></span>
        </div>
        <div className="tb-status">
          <span className={"conn" + (t.liveData ? " on" : "")}>
            <span className="conn-dot" />
            {L("На связи", "Connected")}
          </span>
        </div>
      </header>

      {/* ===== TOOLBAR ===== */}
      <div className="toolbar">
        <button className={"tool-btn wide" + (diffOnly ? " active" : "")} onClick={() => setDiffOnly((v) => !v)} title="Показать только изменения">
          <Icon name="diff" /> <span><Lbl ru="Различия" en="Differences" lang={lang} /></span>
          {dirtyCount ? <span className="badge">{dirtyCount}</span> : null}
        </button>
        <span className="tool-div" />
        <button className="tool-btn" onClick={() => flash(L("Обновлено с устройства", "Refreshed from device"))} title="Обновить / Refresh"><Icon name="refresh" /></button>
        <button className="tool-btn" onClick={undo} disabled={!history.length} title="Отменить / Undo"><Icon name="undo" /></button>
        <button className="tool-btn" onClick={revertAll} disabled={!dirtyCount} title="Вернуть всё / Revert all"><Icon name="redo" /></button>
        <span className="tool-div" />
        <button className={"tool-btn" + (dirtyCount ? " accent" : "")} onClick={save} disabled={!dirtyCount} title="Сохранить / Save"><Icon name="save" /></button>
        <button className="tool-btn" onClick={() => flash(L("Экспорт конфигурации", "Configuration exported"))} title="Экспорт / Export"><Icon name="export" /></button>
        <button className="tool-btn" onClick={() => flash(L("Экспорт в Excel", "Exported to Excel"))} title="Экспорт в Excel"><Icon name="excel" /></button>
        <div className="toolbar-spacer" />
        <button className="tool-btn ghost mobile-only" onClick={() => setDrawer((v) => !v)} title="Дерево / Tree"><Icon name="grid" /></button>
      </div>

      {/* ===== BODY ===== */}
      <div className="body">
        <aside className={"sidebar" + (drawer ? " open" : "")}>
          <div className="search-wrap">
            <Icon name="search" size={15} />
            <input className="search-input" placeholder={L("Поиск параметра…", "Search parameter…")} value={query} onChange={(e) => setQuery(e.target.value)} />
            {query ? <button className="search-clear" onClick={() => setQuery("")}>×</button> : null}
          </div>
          <div className="tree-head"><Lbl ru="Имя" en="Name" lang={lang} /></div>
          <div className="tree-scroll">
            {window.RELAY.tree.map((n) => (
              <TreeNode key={n.id} node={n} depth={0} selected={selected} openSet={openSet}
                onToggle={toggle} onSelect={selectNode} lang={lang} query={query.trim().toLowerCase()} />
            ))}
          </div>
        </aside>
        {drawer ? <div className="scrim" onClick={() => setDrawer(false)} /> : null}

        <main className="content">
          <div className="content-head">
            <div className="crumbs">
              {crumbs.map((c, i) => (
                <React.Fragment key={c.id}>
                  {i ? <span className="crumb-sep">›</span> : null}
                  <span className={"crumb" + (i === crumbs.length - 1 ? " cur" : "")}>{lang === "en" ? c.en : c.ru}</span>
                </React.Fragment>
              ))}
            </div>
            <div className="device-pill">
              <Icon name="bolt" size={14} />
              <select className="device-select" defaultValue={dev.name}>
                <option>{dev.name}</option>
                <option>CM15_4_RRE #2</option>
              </select>
              <Icon name="chevron" size={12} />
            </div>
          </div>

          {viewData ? (
            viewData.sections.length ? (
              <ParamTable data={viewData} nodeKey={node.id} values={values} live={live} lang={lang} dirtySet={dirty} onChange={changeValue} />
            ) : (
              <div className="empty">
                <Icon name="diff" size={26} />
                <p><Lbl ru="Нет изменённых параметров" en="No modified parameters" lang={lang} /></p>
                <button className="link-btn" onClick={() => setDiffOnly(false)}>{L("Показать все", "Show all")}</button>
              </div>
            )
          ) : (
            <div className="empty"><p>{L("Выберите параметр", "Select a parameter")}</p></div>
          )}
        </main>
      </div>

      {toast ? <div className="toast"><Icon name="check" size={15} />{toast}</div> : null}

      {/* ===== TWEAKS ===== */}
      <TweaksPanel>
        <TweakSection label="Visual direction" />
        <TweakRadio label="Look" value={t.theme} options={["refined", "card", "compact"]} onChange={(v) => setTweak("theme", v)} />
        <TweakColor label="Accent" value={t.accent} options={["#2f6fb0", "#3a7a5e", "#5b5fb0", "#9a6a2e"]} onChange={(v) => setTweak("accent", v)} />
        <TweakSection label="Layout" />
        <TweakRadio label="Density" value={t.density} options={["comfortable", "cozy", "compact"]} onChange={(v) => setTweak("density", v)} />
        <TweakRadio label="Language" value={t.lang} options={["ru", "en", "both"]} onChange={(v) => setTweak("lang", v)} />
        <TweakToggle label="Live data" value={t.liveData} onChange={(v) => setTweak("liveData", v)} />
      </TweaksPanel>
    </div>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

